/// dependency-picker: Issue dependencies
private struct DependencyPickerExample0: View {
    private static func status(_ id: String, _ category: String, _ name: String) -> MonarchStatusDefinition {
        switch category {
        case "completed": return MonarchStatusDefinition(name, tone: .success, systemImage: "checkmark.circle.fill")
        case "started": return MonarchStatusDefinition(name, tone: .warning, systemImage: "circle.lefthalf.filled")
        case "backlog": return MonarchStatusDefinition(name, tone: .neutral, systemImage: "circle.dashed")
        default: return MonarchStatusDefinition(name, tone: .neutral, systemImage: "circle")
        }
    }
    private static let issues = [
        MonarchDependencyItem(id: "11", key: "APP-11", title: "Agree the data model", status: Self.status("done", "completed", "Done")),
        MonarchDependencyItem(id: "12", key: "APP-12", title: "Build the import endpoint", status: Self.status("doing", "started", "In progress")),
        MonarchDependencyItem(id: "13", key: "APP-13", title: "Write the migration guide", status: Self.status("todo", "unstarted", "Todo")),
        MonarchDependencyItem(id: "14", key: "APP-14", title: "Add import to settings", status: Self.status("todo", "unstarted", "Todo")),
        MonarchDependencyItem(id: "15", key: "APP-15", title: "Import from spreadsheets", status: Self.status("backlog", "backlog", "Backlog")),

    ]
    @State private var links = [
        MonarchDependencyLink(id: "a", relation: .blockedBy, item: Self.issues.first { $0.id == "11" }!),
        MonarchDependencyLink(id: "b", relation: .blocks, item: Self.issues.first { $0.id == "14" }!),
    ]

    var body: some View {
        MonarchDependencyPicker(
            links: links,
            items: Self.issues,
            excludedIDs: ["12"],
            onAdd: { relation, item in
                links.append(MonarchDependencyLink(id: "\(relation.rawValue)-\(item.id)", relation: relation, item: item))
            },
            onRemove: { link in links.removeAll { $0.id == link.id } }
        )
    }
}

