/// priority-picker: Priority picker
private struct PriorityPickerExample0: View {
    @Environment(\.monarchTheme) private var theme
    @Environment(\.monarchStartsPresented) private var startsPresented
    @State private var isOpen = false
    @State private var priority = Priority.medium

    private enum Priority: CaseIterable, Identifiable {
        case urgent, high, medium, low, unset

        var id: Self { self }

        var name: String {
            switch self {
            case .urgent: "Urgent"
            case .high: "High"
            case .medium: "Medium"
            case .low: "Low"
            case .unset: "No priority"
            }
        }

        var role: MonarchColorRole {
            switch self {
            case .urgent: \.dangerSolid
            case .high: \.warningStrong
            case .medium: \.textDefault
            case .low, .unset: \.textSubtle
            }
        }

        /// Signal bars for high, medium and low (three, two or one lit), as the web draws them.
        @ViewBuilder var icon: some View {
            switch self {
            case .urgent: Image(systemName: "exclamationmark.square.fill")
            case .high: SignalBars(lit: 3)
            case .medium: SignalBars(lit: 2)
            case .low: SignalBars(lit: 1)
            case .unset: Image(systemName: "minus")
            }
        }
    }

    /// Three signal bars, the first `lit` filled and the rest outlined, as the web draws them.
    private struct SignalBars: View {
        let lit: Int

        var body: some View {
            HStack(alignment: .bottom, spacing: 2) {
                ForEach(0..<3, id: \.self) { index in
                    RoundedRectangle(cornerRadius: 1)
                        .fill(index < lit ? AnyShapeStyle(.foreground) : AnyShapeStyle(.clear))
                        .overlay(RoundedRectangle(cornerRadius: 1).strokeBorder(.foreground, lineWidth: 1))
                        .frame(width: 4, height: CGFloat(6 + index * 3))
                }
            }
            .accessibilityHidden(true)
        }
    }

    var body: some View {
        Button {
            isOpen = true
        } label: {
            HStack(spacing: theme.spacing.space2) {
                priority.icon.foregroundStyle(theme.colors[role: priority.role])
                Text(priority.name)
                Image(systemName: "chevron.down")
                    .imageScale(.small)
            }
        }
        .buttonStyle(.monarch(.secondary, size: .sm))
        .onAppear { if startsPresented { isOpen = true } }
        .popover(isPresented: $isOpen, arrowEdge: .top) {
            VStack(alignment: .leading, spacing: 0) {
                ForEach(Priority.allCases) { level in
                    Button {
                        priority = level
                        isOpen = false
                    } label: {
                        HStack(spacing: theme.spacing.space2) {
                            level.icon.foregroundStyle(theme.colors[role: level.role]).frame(width: 20)
                            Text(level.name).monarchTextStyle(.body)
                            Spacer(minLength: theme.spacing.space4)
                            if priority == level {
                                Circle().fill(theme.colors.accentSolid).frame(width: 6, height: 6)
                            }
                        }
                        .foregroundStyle(theme.colors.textDefault)
                        .padding(.horizontal, theme.spacing.space3)
                        .frame(minHeight: 44)
                        .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .accessibilityAddTraits(priority == level ? .isSelected : [])
                }
            }
            .padding(.vertical, theme.spacing.space1)
            .frame(minWidth: 200)
            .presentationCompactAdaptation(.popover)
            .presentationBackground(theme.colors.bgSurface)
        }
    }
}

