/// rule-builder: Scheduled rule with an extra option
private struct RuleBuilderExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var name = "Raise priority of old requests"
    @State private var description = ""
    @State private var triggers: Set<String> = ["hourly"]
    @State private var match = MonarchConditionMatch.all
    @State private var conditions: [MonarchCondition] = [
        MonarchCondition(id: "c1", field: "hoursOpen", operator: .greaterThan, value: .number(24.0)),
    ]
    @State private var actions: [MonarchRuleAction] = [
        MonarchRuleAction(id: "a1", type: "set_priority", parameters: ["priority": .option("high")]),
    ]
    @State private var isOn = true
    @State private var stopsProcessing = false
    @State private var priority = "10"
    @State private var showsErrors = false

    private let events: [(id: String, label: String, description: String?)] = [
        ("created", "Request created", nil),
        ("updated", "Request updated", nil),
        ("replied", "Requester replied", nil),
        ("hourly", "Every hour", "Checks open requests on a schedule."),
    ]
    private let fields = [
        MonarchConditionField(id: "priority", label: "Priority", kind: .select([
            MonarchComboboxOption(id: "low", label: "Low"),
            MonarchComboboxOption(id: "normal", label: "Normal"),
            MonarchComboboxOption(id: "high", label: "High"),
        ])),
        MonarchConditionField(id: "subject", label: "Subject", kind: .text),
        MonarchConditionField(id: "hoursOpen", label: "Hours since created", kind: .number, prompt: "Hours"),
        MonarchConditionField(id: "tags", label: "Tags", kind: .text),
    ]
    private let types = [
        MonarchActionType(id: "set_priority", label: "Set priority", parameters: [
            MonarchActionParameter(key: "priority", label: "Priority", kind: .select([
                MonarchComboboxOption(id: "normal", label: "Normal"),
                MonarchComboboxOption(id: "high", label: "High"),
            ]), isRequired: true),
        ]),
        MonarchActionType(id: "add_tags", label: "Add tags", parameters: [
            MonarchActionParameter(key: "tags", label: "Tags", kind: .tags(suggestions: []), isRequired: true),
        ]),
        MonarchActionType(id: "notify", label: "Notify the team", parameters: [
            MonarchActionParameter(key: "message", label: "Message", kind: .multilineText, isRequired: true),
        ]),
    ]

    private func trigger(_ id: String) -> Binding<Bool> {
        Binding(
            get: { triggers.contains(id) },
            set: { isOn in if isOn { triggers.insert(id) } else { triggers.remove(id) } }
        )
    }

    var body: some View {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
            MonarchTextField("Name", text: $name, isRequired: true)
            MonarchTextField("Description (optional)", text: $description)
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                Text("When").monarchTextStyle(.label)
                Text("The rule is checked whenever any of these happen.")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                ForEach(events, id: \.id) { event in
                    Toggle(isOn: trigger(event.id)) {
                        VStack(alignment: .leading) {
                            Text(event.label)
                            if let description = event.description {
                                Text(description).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                            }
                        }
                    }
                    .toggleStyle(.monarchCheckbox)
                }
            }
            MonarchSectionCard("If", description: "Leave empty to apply every time the rule is checked.") {
                MonarchConditionEditor(
                    conditions: $conditions, fields: fields, match: $match, showsErrors: showsErrors,
                    labels: MonarchConditionEditorLabels(condition: { _ in "" })
                )
            }
            MonarchSectionCard("Then", description: "Actions run in this order.") {
                MonarchActionEditor(actions: $actions, types: types, showsErrors: showsErrors)
            }
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                Text("Options").monarchTextStyle(.label)
                Toggle(isOn: $isOn) {
                    VStack(alignment: .leading) {
                        Text("Rule is on")
                        Text("Rules that are off are kept but never run.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                    }
                }
                .toggleStyle(.monarchCheckbox)
                Toggle(isOn: $stopsProcessing) {
                    VStack(alignment: .leading) {
                        Text("Stop processing")
                        Text("When this rule matches, later rules are skipped for the same event.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                    }
                }
                .toggleStyle(.monarchCheckbox)
            }
            MonarchTextField("Priority (higher runs first)", text: $priority)
            HStack(spacing: MonarchTokens.Space.space3) {
                Spacer()
                MonarchButton("Cancel", variant: .secondary) { showsErrors = false }
                MonarchButton("Save rule", variant: .primary) { showsErrors = true }
            }
        }
        .padding()
        .padding(.top, MonarchTokens.Space.space6)
    }
}

