/// status-picker: Status picker
private struct StatusPickerExample0: View {
    @Environment(\.monarchTheme) private var theme
    @Environment(\.monarchStartsPresented) private var startsPresented
    @State private var isOpen = false
    @State private var statusID = "doing"

    private enum Category: CaseIterable {
        case backlog, unstarted, started, completed, cancelled

        var name: String {
            switch self {
            case .backlog: "Backlog"
            case .unstarted: "Not started"
            case .started: "In progress"
            case .completed: "Completed"
            case .cancelled: "Cancelled"
            }
        }

        var systemImage: String {
            switch self {
            case .backlog: "circle.dashed"
            case .unstarted: "circle"
            case .started: "circle.righthalf.filled"
            case .completed: "checkmark.circle.fill"
            case .cancelled: "xmark.circle.fill"
            }
        }

        var role: MonarchColorRole {
            switch self {
            case .backlog, .cancelled: \.textSubtle
            case .unstarted: \.textMuted
            case .started: \.warningStrong
            case .completed: \.successStrong
            }
        }
    }

    private struct Status: Identifiable {
        let id: String
        let name: String
        let category: Category
    }

    private let statuses = [
        Status(id: "triage", name: "Triage", category: .backlog),
        Status(id: "backlog", name: "Backlog", category: .backlog),
        Status(id: "todo", name: "Todo", category: .unstarted),
        Status(id: "doing", name: "In progress", category: .started),
        Status(id: "review", name: "In review", category: .started),
        Status(id: "done", name: "Done", category: .completed),
        Status(id: "dropped", name: "Won’t do", category: .cancelled),
    ]

    var body: some View {
        let current = statuses.first { $0.id == statusID }
        Button {
            isOpen = true
        } label: {
            HStack(spacing: theme.spacing.space2) {
                if let current {
                    Image(systemName: current.category.systemImage).foregroundStyle(theme.colors[role: current.category.role])
                    Text(current.name)
                }
                Image(systemName: "chevron.down")
                    .imageScale(.small)
            }
        }
        .buttonStyle(.monarch(.secondary, size: .md))
        .onAppear { if startsPresented { isOpen = true } }
        .popover(isPresented: $isOpen, arrowEdge: .top) {
            VStack(alignment: .leading, spacing: 0) {
                ForEach(Category.allCases, id: \.self) { category in
                    let members = statuses.filter { $0.category == category }
                    if !members.isEmpty {
                        Text(category.name)
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                            .padding(.horizontal, theme.spacing.space3)
                            .padding(.top, theme.spacing.space2)
                        ForEach(members) { status in
                            Button {
                                statusID = status.id
                                isOpen = false
                            } label: {
                                HStack(spacing: theme.spacing.space2) {
                                    Image(systemName: category.systemImage)
                                        .foregroundStyle(theme.colors[role: category.role])
                                        .frame(width: 20)
                                    Text(status.name).monarchTextStyle(.body)
                                    Spacer(minLength: theme.spacing.space4)
                                    if statusID == status.id {
                                        Circle().fill(theme.colors.accentSolid).frame(width: 6, height: 6)
                                    }
                                }
                                .foregroundStyle(theme.colors.textDefault)
                                .padding(.horizontal, theme.spacing.space3)
                                .frame(minHeight: 44)
                                .contentShape(Rectangle())
                            }
                            .buttonStyle(.plain)
                            .accessibilityAddTraits(statusID == status.id ? .isSelected : [])
                        }
                    }
                }
            }
            .padding(.vertical, theme.spacing.space1)
            .frame(minWidth: 220)
            .presentationCompactAdaptation(.popover)
            .presentationBackground(theme.colors.bgSurface)
        }
    }
}

/// status-picker: A Monarch trigger that shows the category symbol
private struct StatusPickerExample1: View {
    @Environment(\.monarchTheme) private var theme
    @State private var statusID = "doing"

    private enum Category: CaseIterable {
        case backlog, unstarted, started, completed, cancelled

        var name: String {
            switch self {
            case .backlog: "Backlog"
            case .unstarted: "Not started"
            case .started: "In progress"
            case .completed: "Completed"
            case .cancelled: "Cancelled"
            }
        }

        var systemImage: String {
            switch self {
            case .backlog: "circle.dashed"
            case .unstarted: "circle"
            case .started: "circle.righthalf.filled"
            case .completed: "checkmark.circle.fill"
            case .cancelled: "xmark.circle.fill"
            }
        }

        var role: MonarchColorRole {
            switch self {
            case .backlog, .cancelled: \.textSubtle
            case .unstarted: \.textMuted
            case .started: \.warningStrong
            case .completed: \.successStrong
            }
        }
    }

    private struct Status: Identifiable {
        let id: String
        let name: String
        let category: Category
    }

    private let statuses = [
        Status(id: "triage", name: "Triage", category: .backlog),
        Status(id: "todo", name: "Todo", category: .unstarted),
        Status(id: "doing", name: "In progress", category: .started),
        Status(id: "review", name: "In review", category: .started),
        Status(id: "done", name: "Done", category: .completed),
        Status(id: "dropped", name: "Won’t do", category: .cancelled),
    ]

    var body: some View {
        let current = statuses.first { $0.id == statusID }
        Menu {
            Picker("Status", selection: $statusID) {
                ForEach(Category.allCases, id: \.self) { category in
                    let members = statuses.filter { $0.category == category }
                    if !members.isEmpty {
                        Section(category.name) {
                            ForEach(members) { status in
                                Label(status.name, systemImage: category.systemImage).tag(status.id)
                            }
                        }
                    }
                }
            }
            .pickerStyle(.menu)
        } label: {
            Label {
                Text(current?.name ?? "No status")
            } icon: {
                Image(systemName: current?.category.systemImage ?? "circle.dashed")
                    .foregroundStyle(theme.colors[role: current?.category.role ?? \.textSubtle])
            }
        }
        .buttonStyle(.monarch(.secondary, size: .sm))
        .accessibilityLabel("Status: \(current?.name ?? "No status")")
    }
}

/// stepper: Wizard with clickable completed steps
private struct StepperExample0: View {
    @State private var current = 1
    @State private var furthest = 1

    var body: some View {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
            MonarchStepper(
                [
                    MonarchStepperStep(id: "basics", label: "Basics"),
                    MonarchStepperStep(id: "access", label: "Access"),
                    MonarchStepperStep(id: "branding", label: "Branding", isOptional: true),
                    MonarchStepperStep(id: "review", label: "Review"),
                ],
                current: current,
                furthest: furthest
            ) { _, index in
                current = index
                furthest = max(furthest, index)
            }
            HStack(spacing: MonarchTokens.Space.space2) {
                MonarchButton("Back", variant: .secondary) {
                    current -= 1
                }
                .disabled(current == 0)
                MonarchButton("Continue", variant: .primary) {
                    current += 1
                    furthest = max(furthest, current)
                }
                .disabled(current == 3)
            }
        }
    }
}

/// stepper: A vertical stepper whose reached steps can be selected
private struct StepperExample1: View {
    @State private var current = 2
    private let steps = [
        MonarchStepperStep(id: "plan", label: "Plan"),
        MonarchStepperStep(id: "team", label: "Team", description: "Invite the people you work with", isOptional: true),
        MonarchStepperStep(id: "billing", label: "Billing"),
        MonarchStepperStep(id: "review", label: "Review"),
    ]

    var body: some View {
        MonarchStepper(steps, current: current, furthest: 2, orientation: .vertical) { _, index in
