            MonarchTimesheetDiffEntry(id: "e2", date: Date(timeIntervalSince1970: 1_768_262_400), minutes: 60, project: "Internal", isBillable: false),
            MonarchTimesheetDiffEntry(id: "e3", date: Date(timeIntervalSince1970: 1_768_348_800), minutes: 90, project: "Mobile app"),
        ]
    }
    private var resubmitted: [MonarchTimesheetDiffEntry] {
